            exp_out='- name: result\n  type: string\n  specification: Status message indicating success, updated fields, or reason for failure.',
            exp_in='- name: event_id\n  type: string\n  specification: Identifier of the calendar event to modify.\n- name: title\n  type: string\n  specification: New title (optional).\n- name: date\n  type: string\n  specification: New event date (optional).\n- name: time\n  type: string\n  specification: New event time (optional).\n- name: attendees\n  type: string\n  specification: Comma-separated attendee emails to replace the list (optional).\n- name: details\n  type: string\n  specification: Replacement notes/details (optional, stored as "notes").',
